import { RARITY } from '../../constants/core.ts';
import {
    POKEMON_ULTIMATE_ABILITIES,
    GENERIC_ULTIMATES,
    ULTIMATE_CHARGE_NEEDED_MULTIPLIER,
    ENEMY_PVP_ULTIMATE_CHARGE_NEEDED_DIVISOR,
} from '../../constants/balance/talentsAndCombat.ts';
import type { UltimateAbility } from '../types/creature.js';

function applyUltimateChargeMultiplier(ability: UltimateAbility): UltimateAbility {
    if (!ability) return GENERIC_ULTIMATES[RARITY.COMMON];
    if ((ULTIMATE_CHARGE_NEEDED_MULTIPLIER as number) === 1) return ability;

    const rawCharge = Number(ability.chargeNeeded) || 100;
    const chargeNeeded = Math.max(1, Math.round(rawCharge * (ULTIMATE_CHARGE_NEEDED_MULTIPLIER as number)));
    const effect = ability.effect;
    const bonusCharge = effect?.bonusCharge;
    const scaledEffect =
        effect && bonusCharge != null
            ? { ...effect, bonusCharge: Math.max(0, Math.round(bonusCharge * (ULTIMATE_CHARGE_NEEDED_MULTIPLIER as number))) }
            : effect;

    return { ...ability, chargeNeeded, effect: scaledEffect };
}

/** Scale ultimate charge for enemy PvP (after global multiplier). */
export function scaleUltimateChargeForEnemyPvp(ability: UltimateAbility): UltimateAbility {
    if (!ability) return ability;
    if ((ENEMY_PVP_ULTIMATE_CHARGE_NEEDED_DIVISOR as number) === 1) return ability;

    const rawCharge = Number(ability.chargeNeeded) || 100;
    const chargeNeeded = Math.max(1, Math.round(rawCharge / (ENEMY_PVP_ULTIMATE_CHARGE_NEEDED_DIVISOR as number)));
    const effect = ability.effect;
    const bonusCharge = effect?.bonusCharge;
    const scaledEffect =
        effect && bonusCharge != null
            ? { ...effect, bonusCharge: Math.max(0, Math.round(bonusCharge / (ENEMY_PVP_ULTIMATE_CHARGE_NEEDED_DIVISOR as number))) }
            : effect;

    return { ...ability, chargeNeeded, effect: scaledEffect };
}

/** Resolve personalized ultimate by species name, or generic fallback by rarity. */
export function resolveUltimateAbility(speciesName: string | null | undefined, rarity: string | null | undefined): UltimateAbility {
    const cleanName = String(speciesName || '').trim();
    const personalized = (POKEMON_ULTIMATE_ABILITIES as unknown as Record<string, UltimateAbility | undefined>)[cleanName];
    if (personalized) return applyUltimateChargeMultiplier(personalized);

    const r = String(rarity || RARITY.COMMON).toLowerCase();
    if (r === RARITY.LEGENDARY) return applyUltimateChargeMultiplier(GENERIC_ULTIMATES[RARITY.LEGENDARY]);
    if (r === RARITY.EPIC) return applyUltimateChargeMultiplier(GENERIC_ULTIMATES[RARITY.EPIC]);
    if (r === RARITY.RARE) return applyUltimateChargeMultiplier(GENERIC_ULTIMATES[RARITY.RARE]);
    return applyUltimateChargeMultiplier(GENERIC_ULTIMATES[RARITY.COMMON]);
}
